def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]
    my_prev, opp_prev = history[-2] if n >= 2 else ('C', 'C')

    opp_c = sum(1 for a, b in history if b == 'C')
    opp_d = n - opp_c
    my_d = sum(1 for a, b in history if a == 'D')

    forgive = 0
    for i in range(1, n):
        if history[i-1][0] == 'D' and history[i][1] == 'C':
            forgive += 1

    recent = history[-10:]
    recent_opp_d = sum(1 for a, b in recent if b == 'D')

    # Always defect against an always-defector.
    if n >= 10 and opp_c <= 2:
        return 'D'

    # Exploit an opponent that is very forgiving.
    if my_d > 0 and forgive >= my_d * 0.7 and n >= 20:
        if n >= 95:
            return 'D'
        if n >= 80 and rng.random() < 0.5:
            return 'D'
        if rng.random() < 0.25:
            return 'D'
        return 'C'

    # Endgame defection.
    if n >= 99:
        return 'D'
    if n >= 97 and opp_c >= n - 5:
        return 'D'

    # Contrition: if we defected and opponent defected, and we were cooperative before,
    # apologize by cooperating to break mutual defection.
    if my_last == 'D' and opp_last == 'D' and my_prev == 'C' and opp_prev == 'C':
        return 'C'

    # If opponent just defected.
    if opp_last == 'D':
        if my_last == 'D':
            streak = 0
            for a, b in reversed(history):
                if b == 'D':
                    streak += 1
                else:
                    break
            if streak >= 3 and rng.random() < 0.3:
                return 'C'
            return 'D'
        else:
            if recent_opp_d == 1 and n >= 10:
                if rng.random() < 0.3:
                    return 'C'
            return 'D'

    # Opponent just cooperated.
    if my_last == 'D':
        return 'C'

    # Both cooperated: probe if opponent seems forgiving.
    if n >= 20:
        if forgive > 0 and forgive >= my_d * 0.5:
            if rng.random() < 0.15:
                return 'D'
        if rng.random() < 0.05:
            return 'D'

    return 'C'
